--- a/axum/src/routing/tests/fallback.rs
+++ b/axum/src/routing/tests/fallback.rs
@@ -3,6 +3,29 @@
 use super::*;
 use crate::middleware::{map_request, map_response};

+#[crate::test]
+async fn fallback_service_with_nested_serve_dir() {
+    for prefix in ["/", "/static"] {
+        let routes_static = Router::new().nest_service(
+            prefix,
+            get_service(tower_http::services::ServeDir::new(env!(
+                "CARGO_MANIFEST_DIR"
+            ))),
+        );
+        let app = Router::new().fallback_service(routes_static);
+        let client = TestClient::new(app);
+
+        let path = format!("{}/README.md", prefix.trim_end_matches('/'));
+        let res = client.get(&path).send().await;
+        assert_eq!(res.status(), StatusCode::OK);
+        assert_eq!(res.text().await, include_str!("../../../README.md"));
+
+        let path = format!("{}/does-not-exist", prefix.trim_end_matches('/'));
+        let res = client.get(&path).send().await;
+        assert_eq!(res.status(), StatusCode::NOT_FOUND);
+    }
+}
+
 #[crate::test]
 async fn basic() {
     let app = Router::new()
--- a/axum/src/extract/matched_path.rs
+++ b/axum/src/extract/matched_path.rs
@@ -391,4 +391,28 @@
         let res = client.get("/foo/bar").send().await;
         assert_eq!(res.status(), StatusCode::OK);
     }
+
+    #[crate::test]
+    async fn extracting_on_nested_handler_after_matched_route() {
+        async fn handler(path: Option<MatchedPath>) -> &'static str {
+            assert!(path.is_none());
+            "nested"
+        }
+
+        let service = Router::new().nest_service("/", handler.into_service());
+        let apps = [
+            Router::new().fallback_service(service.clone()),
+            Router::new().route("/*path", crate::routing::get_service(service)),
+        ];
+
+        for app in apps {
+            let client = TestClient::new(app);
+
+            let res = client.get("/foo/bar").send().await;
+            assert_eq!(res.status(), StatusCode::OK);
+            assert_eq!(res.text().await, "nested");
+        }
+    }
 }
